'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );


// MAIN //

/**
* Evaluates the probability density function (PDF) for a Burr (type III) distribution with first shape parameter `alpha` and second shape parameter `beta` at a value `x`.
*
* @param {number} x - input value
* @param {PositiveNumber} alpha - first shape parameter
* @param {PositiveNumber} beta - second shape parameter
* @returns {number} evaluated PDF
*
* @example
* var v = pdf( 1, 1.0, 1.0 );
* // returns 0.25
*
* @example
* var v = pdf( 4, 4.0, 4.0 );
* // returns ~0.0153
*
* @example
* var v = pdf( 3, 3.0, 3.0 );
* // returns ~0.096
*
* @example
* var v = pdf( 1, NaN, 1.0 );
* // returns NaN
*
* @example
* var v = pdf( 1, 1.0, NaN );
* // returns NaN
*/
function pdf( x, alpha, beta ) {
	var out;
	if (
		isnan( x ) ||
		isnan( alpha ) ||
		isnan( beta ) ||
		alpha <= 0.0 ||
		beta <= 0.0 ||
		x <= 0.0
	) {
		return NaN;
	}
	out = alpha * beta;
	out *= pow( x, -alpha-1 );
	out /= pow( 1 + pow( x, -alpha ), beta + 1 );
	return out;
}


// EXPORTS //

module.exports = pdf;
